import requests, re, json, os, time, sys
from collections import defaultdict, deque
from urllib.parse import quote

HEADERS = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "en-US,en;q=0.5",
}

def fetch_scholar_page(user_id):
    url = f"https://scholar.google.com/citations?user={user_id}&hl=en"
    try:
        r = requests.get(url, headers=HEADERS, timeout=30)
        if r.status_code != 200:
            return None
        return r.text
    except Exception as e:
        print(f"Error fetching {user_id}: {e}")
        return None

def extract_name(html):
    m = re.search(r'<title>\s*‪([^‪]+)‬\s*-\s*Google Scholar', html)
    if m:
        return m.group(1).strip()
    m = re.search(r'<div[^>]*class="[^"]*gsc_prf_in[^"]*"[^>]*>([^<]+)</div>', html)
    if m:
        return m.group(1).strip()
    return None

def extract_coauthors_from_html(html):
    """Extract co-authors from the profile page."""
    coauthors = set()
    # Look for co-author links
    pattern = r'href="/citations\?user=([^"]+)"[^>]*>([^<]+)</a>'
    matches = re.findall(pattern, html)
    for user_id, name in matches:
        if user_id and name and len(name) > 1:
            coauthors.add((user_id.strip(), name.strip()))
    return coauthors

def get_scholar_profile(user_id, cache_dir="/tmp_workspace/scholar_cache"):
    os.makedirs(cache_dir, exist_ok=True)
    cache_file = os.path.join(cache_dir, f"{user_id}.json")

    if os.path.exists(cache_file):
        with open(cache_file, 'r') as f:
            return json.load(f)

    html = fetch_scholar_page(user_id)
    if not html:
        return None

    name = extract_name(html)
    coauthors = extract_coauthors_from_html(html)

    profile = {
        "user_id": user_id,
        "name": name,
        "coauthors": list(coauthors)
    }

    with open(cache_file, 'w') as f:
        json.dump(profile, f)

    time.sleep(2)  # Be polite to Google
    return profile

def bfs_scholar_connection(start_id, end_id, max_depth=4):
    """BFS to find shortest connection between two scholars."""
    visited = set()
    queue = deque([(start_id, [start_id])])

    while queue:
        current_id, path = queue.popleft()

        if len(path) > max_depth + 1:
            continue

        if current_id == end_id and len(path) > 1:
            return path

        if current_id in visited:
            continue

        visited.add(current_id)

        profile = get_scholar_profile(current_id)
        if not profile:
            continue

        print(f"Exploring {profile.get('name', current_id)} (depth {len(path)}), found {len(profile.get('coauthors', []))} coauthors")

        for coauthor_id, coauthor_name in profile.get('coauthors', []):
            if coauthor_id not in visited:
                new_path = path + [coauthor_id]
                if coauthor_id == end_id:
                    return new_path
                queue.append((coauthor_id, new_path))

    return None

def main():
    A_ID = "hUrX-LMAAAAJ"
    B_ID = "JicYPdAAAAAJ"

    print("Fetching scholar A profile...")
    a_profile = get_scholar_profile(A_ID)
    print(f"A: {a_profile.get('name', 'Unknown')}")
    print(f"Coauthors found: {len(a_profile.get('coauthors', []))}")

    print("\nFetching scholar B profile...")
    b_profile = get_scholar_profile(B_ID)
    print(f"B: {b_profile.get('name', 'Unknown')}")

    print("\nSearching for connection...")
    connection = bfs_scholar_connection(A_ID, B_ID, max_depth=4)

    if connection:
        print(f"\nConnection found! Path length: {len(connection) - 1}")
        print("Path:")
        for user_id in connection:
            profile = get_scholar_profile(user_id)
            print(f"  - {profile.get('name', user_id)} ({user_id})")
    else:
        print("\nNo connection found within search depth.")

    # Save results
    os.makedirs("/tmp_workspace/results", exist_ok=True)
    with open("/tmp_workspace/results/results.md", 'w') as f:
        f.write("# Scholar Connection Results\n\n")
        f.write(f"## Scholar A\n- Name: {a_profile.get('name', 'Unknown')}\n")
        f.write(f"- Google Scholar ID: {A_ID}\n")
        f.write(f"- URL: https://scholar.google.com/citations?user={A_ID}\n\n")

        f.write(f"## Scholar B\n- Name: {b_profile.get('name', 'Unknown')}\n")
        f.write(f"- Google Scholar ID: {B_ID}\n")
        f.write(f"- URL: https://scholar.google.com/citations?user={B_ID}\n\n")

        if connection:
            f.write("## Connection Found\n\n")
            f.write(f"**Shortest path length:** {len(connection) - 1} collaboration(s)\n\n")
            f.write("**Path:**\n\n")
            for i, user_id in enumerate(connection):
                profile = get_scholar_profile(user_id)
                name = profile.get('name', user_id)
                f.write(f"{i+1}. **{name}** ({user_id})\n")
                if i < len(connection) - 1:
                    f.write(f"   ↓ collaborated with\n")
            f.write("\n")
        else:
            f.write("## Result\n\nNo connection found within the search depth.\n\n")

        f.write("## Co-authors of Scholar A\n\n")
        for coauthor_id, coauthor_name in a_profile.get('coauthors', [])[:20]:
            f.write(f"- {coauthor_name} ({coauthor_id})\n")

    print("\nResults saved to /tmp_workspace/results/results.md")

if __name__ == "__main__":
    main()

